dc Vin 480m 520m 0.1m
let vodiff = v(vop) - v(vom)
let gain_deriv = deriv(vodiff)
meas dc max_gain max gain_deriv

* 3. AC Frequency Response
ac dec 50 1k 10G
let vdiff = v(vop) - v(vom)
let gain_db = vdb(vop) - vdb(vom)
meas ac dc_gain find gain_db at=1k
meas ac ugbw when gain_db=0 fall=1

* 4. Transient step response (10 ns period pulse)
tran 50p 30n
meas tran vdiff_max max v(vop)-v(vom)
meas tran vdiff_min min v(vop)-v(vom)
meas tran t_settle trig v(Vin) val=550m rise=1 targ v(vop)-v(vom) val=0.198 rise=1

print max_gain dc_gain ugbw idd_total vocm
quit
.endc
